using NUnit.Framework; using PortalNes.Emulator.Mappers;
namespace PortalNes.Tests { public sealed class Mapper000Tests { [Test] public void Nrom128_MirrorsPrg() { var p=new byte[16384];p[0]=0x12;var m=new Mapper000(p,new byte[8192]);Assert.That(m.CpuRead(0x8000),Is.EqualTo(0x12));Assert.That(m.CpuRead(0xC000),Is.EqualTo(0x12)); } [Test] public void Nrom256_MapsFullPrg() { var p=new byte[32768];p[0]=0x12;p[16384]=0x34;var m=new Mapper000(p,new byte[8192]);Assert.That(m.CpuRead(0x8000),Is.EqualTo(0x12));Assert.That(m.CpuRead(0xC000),Is.EqualTo(0x34)); } [Test] public void PpuRead_ReturnsChr() { var c=new byte[8192];c[8191]=0xAB;Assert.That(new Mapper000(new byte[16384],c).PpuRead(0x1FFF),Is.EqualTo(0xAB)); } } }
